import sys


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 50000))

    memo: dict[str, int | str] = {}
    visiting: set[str] = set()

    def tokenize(s: str) -> list[tuple[str, str]]:
        tokens: list[tuple[str, str]] = []
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch.isspace():
                i += 1
            elif ch in "+-*/(),:":
                tokens.append((ch, ch))
                i += 1
            elif ch in "<>=":
                if i + 1 < n and s[i : i + 2] in ("<>", "<=", ">="):
                    op = s[i : i + 2]
                    tokens.append((op, op))
                    i += 2
                else:
                    tokens.append((ch, ch))
                    i += 1
            elif ch.isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(("NUM", s[i:j]))
                i = j
            elif ch.isalpha():
                j = i
                while j < n and s[j].isalnum():
                    j += 1
                tokens.append(("ID", s[i:j]))
                i = j
            else:
                raise ValueError(f"Unexpected character: {ch}")
        return tokens

    def parse_cell(name: str) -> tuple[int, int]:
        return ord(name[0]), int(name[1:])

    def eval_tokens(tokens: list[tuple[str, str]]) -> int | str:
        pos = 0
        n = len(tokens)

        def peek() -> tuple[str, str] | None:
            return tokens[pos] if pos < n else None

        def consume() -> tuple[str, str]:
            nonlocal pos
            tok = tokens[pos]
            pos += 1
            return tok

        def parse_formula() -> int | str:
            val = parse_term()
            while (tok := peek()) is not None and tok[0] in ("+", "-"):
                op = consume()[0]
                if isinstance(val, str):
                    # Skip evaluating right-hand side on error, but still advance parser
                    skip_term()
                    continue
                rhs = parse_term()
                if isinstance(rhs, str):
                    val = rhs
                elif op == "+":
                    val = val + rhs
                else:
                    val = val - rhs
            return val

        def skip_term() -> None:
            skip_unary()
            while (tok := peek()) is not None and tok[0] in ("*", "/"):
                consume()
                skip_unary()

        def skip_unary() -> None:
            while (tok := peek()) is not None and tok[0] == "-":
                consume()
            skip_atom()

        def skip_atom() -> None:
            tok = consume()
            if tok[0] == "NUM":
                return
            if tok[0] == "(":
                depth = 1
                while depth > 0:
                    t = consume()
                    if t[0] == "(":
                        depth += 1
                    elif t[0] == ")":
                        depth -= 1
                return
            if tok[0] == "ID":
                if (nxt := peek()) is not None and nxt[0] == "(":
                    consume()
                    depth = 1
                    while depth > 0:
                        t = consume()
                        if t[0] == "(":
                            depth += 1
                        elif t[0] == ")":
                            depth -= 1
                return

        def skip_formula() -> None:
            skip_term()
            while (tok := peek()) is not None and tok[0] in ("+", "-"):
                consume()
                skip_term()

        def parse_term() -> int | str:
            val = parse_unary()
            while (tok := peek()) is not None and tok[0] in ("*", "/"):
                op = consume()[0]
                if isinstance(val, str):
                    skip_unary()
                    continue
                rhs = parse_unary()
                if isinstance(rhs, str):
                    val = rhs
                elif op == "*":
                    val = val * rhs
                else:
                    if rhs == 0:
                        val = "#DIV/0!"
                    else:
                        q = abs(val) // abs(rhs)
                        val = -q if (val < 0) ^ (rhs < 0) else q
            return val

        def parse_unary() -> int | str:
            neg = False
            while (tok := peek()) is not None and tok[0] == "-":
                consume()
                neg = not neg
            val = parse_atom()
            if isinstance(val, str):
                return val
            return -val if neg else val

        def parse_atom() -> int | str:
            tok = consume()
            if tok[0] == "NUM":
                return int(tok[1])
            if tok[0] == "(":
                val = parse_formula()
                consume()  # ')'
                return val
            # ID: either function call or cell name
            name = tok[1]
            if (nxt := peek()) is not None and nxt[0] == "(":
                consume()  # '('
                if name == "IF":
                    return eval_if()
                return eval_agg(name)
            return eval_cell(name)

        def eval_if() -> int | str:
            left = parse_formula()
            op = consume()[0]
            if isinstance(left, str):
                skip_formula()
                consume()  # ','
                skip_formula()
                consume()  # ','
                skip_formula()
                consume()  # ')'
                return left

            right = parse_formula()
            consume()  # ','
            if isinstance(right, str):
                skip_formula()
                consume()  # ','
                skip_formula()
                consume()  # ')'
                return right

            if op == "=":
                cond = left == right
            elif op == "<>":
                cond = left != right
            elif op == "<":
                cond = left < right
            elif op == "<=":
                cond = left <= right
            elif op == ">":
                cond = left > right
            else:
                cond = left >= right

            if cond:
                res = parse_formula()
                consume()  # ','
                skip_formula()
                consume()  # ')'
                return res
            else:
                skip_formula()
                consume()  # ','
                res = parse_formula()
                consume()  # ')'
                return res

        def eval_agg(func: str) -> int | str:
            values: list[int] = []
            err: str | None = None

            while True:
                if err is not None:
                    # Skip remaining arguments up to matching ')'
                    depth = 1
                    while depth > 0:
                        t = consume()
                        if t[0] == "(":
                            depth += 1
                        elif t[0] == ")":
                            depth -= 1
                    return err

                # Check if argument is a range: ID ':' ID
                if (
                    pos + 1 < n
                    and tokens[pos][0] == "ID"
                    and tokens[pos + 1][0] == ":"
                ):
                    c1_name = consume()[1]
                    consume()  # ':'
                    c2_name = consume()[1]
                    c1, r1 = parse_cell(c1_name)
                    c2, r2 = parse_cell(c2_name)
                    r_min, r_max = min(r1, r2), max(r1, r2)
                    c_min, c_max = min(c1, c2), max(c1, c2)
                    for r in range(r_min, r_max + 1):
                        for c in range(c_min, c_max + 1):
                            cname = f"{chr(c)}{r}"
                            if cname in cells:
                                v = eval_cell(cname)
                                if isinstance(v, str):
                                    err = v
                                    break
                                values.append(v)
                        if err is not None:
                            break
                else:
                    v = parse_formula()
                    if isinstance(v, str):
                        err = v
                    else:
                        values.append(v)

                nxt = peek()
                if nxt is not None and nxt[0] == ",":
                    consume()
                else:
                    if err is None:
                        consume()  # ')'
                    else:
                        # If err happened on the last argument, consume ')'
                        # If ',' follows, loop will skip remaining args and consume ')'
                        if nxt is not None and nxt[0] == ")":
                            consume()
                            return err
                        continue
                    break

            if err is not None:
                return err
            if not values:
                return 0
            if func == "SUM":
                return sum(values)
            if func == "MIN":
                return min(values)
            return max(values)

        return parse_formula()

    def eval_cell(name: str) -> int | str:
        if name in memo:
            return memo[name]
        if name not in cells:
            return 0
        if name in visiting:
            return "#CYCLE!"

        visiting.add(name)
        content = cells[name]
        if content.startswith("="):
            tokens = tokenize(content[1:])
            res = eval_tokens(tokens)
        else:
            res = int(content)
        visiting.remove(name)
        memo[name] = res
        return res

    return {name: eval_cell(name) for name in cells}
